BEGIN TRANSACTION;
CREATE TABLE api_usage (
  month    TEXT NOT NULL,
  provider TEXT NOT NULL,
  calls    INTEGER NOT NULL DEFAULT 0,
  units    INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (month, provider)
);
CREATE TABLE fetch_log (
  id        INTEGER PRIMARY KEY AUTOINCREMENT,
  ts        TEXT NOT NULL,
  provider  TEXT NOT NULL,
  win_from  TEXT,
  win_to    TEXT,
  ok        INTEGER NOT NULL,
  n_arr     INTEGER DEFAULT 0,
  n_dep     INTEGER DEFAULT 0,
  note      TEXT
);
CREATE TABLE fids_flights (
  key          TEXT PRIMARY KEY,
  direction    TEXT NOT NULL CHECK (direction IN ('ARR','DEP')),
  number       TEXT,
  callsign     TEXT,
  airline      TEXT,
  airline_iata TEXT,
  airline_icao TEXT,
  other_iata   TEXT,
  other_icao   TEXT,
  other_city   TEXT,
  other_cc     TEXT,
  sched_local  TEXT NOT NULL,
  est_local    TEXT,
  actual_local TEXT,
  status       TEXT,
  terminal     TEXT,
  gate         TEXT,
  aircraft     TEXT,
  reg          TEXT,
  first_seen   TEXT,
  updated_at   TEXT
);
CREATE TABLE meta (
  key   TEXT PRIMARY KEY,
  value TEXT
);
CREATE TABLE sightings (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  day          TEXT NOT NULL,
  icao24       TEXT NOT NULL,
  callsign     TEXT NOT NULL DEFAULT '',
  airline      TEXT,
  airline_key  TEXT,
  airline_iata TEXT,
  type_code    TEXT,
  type_name    TEXT,
  reg          TEXT,
  direction    TEXT,
  origin_iata  TEXT,
  origin_city  TEXT,
  dest_iata    TEXT,
  dest_city    TEXT,
  first_seen   TEXT NOT NULL,
  last_seen    TEXT NOT NULL,
  min_dist_km  REAL,
  max_alt_ft   INTEGER,
  UNIQUE (day, icao24, callsign)
);
CREATE INDEX idx_fids_dir_sched ON fids_flights (direction, sched_local);
CREATE INDEX idx_sightings_day ON sightings (day);
CREATE INDEX idx_sightings_last_seen ON sightings (last_seen DESC, id DESC);
DELETE FROM "sqlite_sequence";
COMMIT;
